Select	p21_view_check_hdr.hdrxxxxdef,p21_view_check_hdr.check_no header_number,p21_view_check_hdr.check_no,p21_view_check_hdr.check_date,p21_view_check_hdr.vendor_id,p21_view_check_hdr.vendor_name,p21_view_check_hdr.format_vendor_addr1,p21_view_check_hdr.format_vendor_addr2,/* Pil YPL 2007-04-03 - Case# 525417: The check is only displaying 3 fields of format_vendor_addr, 
	and for vendors for which we have all four fields, the last one is not showing. To take care of 
	this problem we decided to concatenate	the data of fields 3 and 4, leaving the remaining 
	functionality intact. */CASE WHEN LEN(p21_view_check_hdr.format_vendor_addr3) > 0 THENp21_view_check_hdr.format_vendor_addr3 + ' '+ p21_view_check_hdr.format_vendor_addr4ELSE p21_view_check_hdr.format_vendor_addr4END 'format_vendor_addr3',NULL 'format_vendor_addr4',p21_view_check_hdr.mail_address1,p21_view_check_hdr.mail_address2,p21_view_check_hdr.mail_city,p21_view_check_hdr.mail_state,p21_view_check_hdr.mail_postal_code,p21_view_check_hdr.mail_country,p21_view_check_hdr.bank_name,p21_view_check_hdr.bank_branch,p21_view_check_hdr.bank_code,p21_view_check_hdr.bank_address1,p21_view_check_hdr.bank_address2,p21_view_check_hdr.bank_no,p21_view_check_hdr.gl_account_no,p21_view_check_hdr.transit_code,p21_view_check_hdr.account_no,p21_view_check_hdr.fed_res_code,p21_view_check_hdr.written_amount_text,p21_view_check_hdr.company_name,p21_view_check_hdr.format_company_addr1,p21_view_check_hdr.format_company_addr2,p21_view_check_hdr.format_company_addr3,p21_view_check_hdr.format_company_addr4,p21_view_check_hdr.phys_address1,p21_view_check_hdr.phys_address2,p21_view_check_hdr.phys_city,p21_view_check_hdr.phys_state,	p21_view_check_hdr.phys_postal_code,p21_view_check_hdr.central_phone_number,p21_view_check_hdr.transit_number,p21_view_check_hdr.account_number,p21_view_check_hdr.chk_no,p21_view_check_hdr.used_in_us,CASE COALESCE(bank_accounts.number_of_sigs,'0') WHEN '0' THENp21_view_check_hdr.amount_req_two_sigs	ELSE COALESCE(bank_accounts.amount_req_two_sigs,	0)END 'amount_req_two_sig',CASE COALESCE(bank_accounts.number_of_sigs,'0') WHEN '0' THENp21_view_check_hdr.number_of_sigs	ELSE bank_accounts.number_of_sigsEND 'amount_req_two_sig',p21_view_check_hdr.codes,p21_view_check_hdr.check_label,p21_view_check_hdr.check_amount,	p21_view_check_hdr.sign_line1,p21_view_check_hdr.sign_line2,p21_view_check_hdr.sign_label,p21_view_check_hdr.check_date 'iso_date','' written_amount_text_can,p21_view_check_hdr.check_amount 'check_amount_can',p21_view_check_hdr.eft,p21_view_check_hdr.mail_address3,p21_view_check_hdr.phys_address3From p21_view_check_hdrInner Join bank_accountsON p21_view_check_hdr.company_number = bank_accounts.company_noAND p21_view_check_hdr.bank_no = bank_accounts.bank_noWHERE ( p21_view_check_hdr.company_number = '1') and( p21_view_check_hdr.bank_number = 13 ) and( p21_view_check_hdr.currency_id = 1) and ( p21_view_check_hdr.check_no >= '001277' andp21_view_check_hdr.check_no <= '001277' ) AND( 'Y' = 'N' OR edi_check = 'N' )AND eft = 'N'